head.script:
/*
 * [재현 시나리오]
 * 1. 창 열기 클릭 → WindowContainer 안에 창 생성 (고객 조건: frameMode "pageFrame")
 * 2. 창 안에서 "dataList 다운로드" 클릭
 *    현상 1: processMsg가 창 내부가 아닌 전체 화면(top)에 DIM으로 표시됨
 *    현상 2: 다운로드 완료 후에도 processMsg가 사라지지 않음
 * ※ frameMode "wframe"으로 생성해도 동일 재현 확인됨 (2026-07-23)
 */
scwin.onpageload = function () {
};

/* 현재 화면과 같은 폴더 경로를 반환 (AI 개발가이드 pageFrame_createWindow_WindowContainer 샘플과 동일 패턴) */
scwin.getfolderPath = function () {
    var currentPath = window.location.href;
    var folderPath;
    if (currentPath.includes("mainContainer")) {
        const cmtFrame = $p.getComponentById($p.getFrameId());
        currentPath = cmtFrame.getSrc();
        folderPath = currentPath.substring(0, currentPath.lastIndexOf('/'));
    } else {
        folderPath = currentPath.split('w2xPath=')[1].substring(0, currentPath.split('w2xPath=')[1].lastIndexOf('/'));
    }
    return folderPath;
};

scwin.btn_openWindow_onclick = function () {
    var tmpSrc = scwin.getfolderPath() + "/WindowContainer_processMsgFrame_WAEA-1043_(WSQ-6427)_content.xml";
    wdc_main.createWindow({
        "title" : "대량데이타 조회",
        "src" : tmpSrc,
        "windowId" : "win_sample",
        "frameMode" : "pageFrame"
    });
};
